      g.on('click', function () {
        state.selected = (state.selected === i) ? -1 : i;
        redraw();
      });
      g.on('mousemove', function (e) {
        showTooltip('h' + (i + 1) + ': owns θ' + (i + 1) + '₀, θ' + (i + 1) + '₁, φ' + (i + 1) + ' — click to isolate', e);
      });
      g.on('mouseleave', hideTooltip);
    })(k);
  }

  // param count annotation (bottom right)
  var total = 3 * N + 1;
  draw.text('parameters: 3×' + N + ' + 1 (φ₀) = ' + total)
    .font({ size: 13, family: 'serif' }).fill('#555').move(W - 210, H - 26);
}

function applyState() {
  document.getElementById('labelViewInput').checked = state.labeled;
  document.getElementById('hiddenUnitCountInput').value = state.N;
  document.getElementById('hiddenUnitCountVal').value = state.N;
  redraw();
}

function toggle_labelView(on) { state.labeled = on; state.selected = -1; redraw(); }
function update_hiddenUnitCount(v) { state.N = v; state.selected = -1; redraw(); }

function goStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[stepIdx];
  state.labeled = s.state.labeled;
  state.N = s.state.N;
  state.selected = s.state.selected;
  document.getElementById('demoNarration').textContent = s.title + ' — ' + s.narration;
  document.getElementById('stepLabel').textContent = (stepIdx + 1) + '/' + steps.length;
  applyState();
}
function nextStep() { goStep(stepIdx + 1); }
function prevStep() { goStep(stepIdx - 1); }

goStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: A shallow neural network computes y as a linear combination (weights φ) of hidden units, where each hidden unit h_i is itself a linear function (weights θ_{i0}, θ_{i1}) of the input x passed through an activation — so the θ parameters govern the input-to-hidden transformation and the φ parameters govern the hidden-to-output combination.
KEY INSIGHT (what students should walk away understanding): Every hidden unit contributes exactly one self-contained trio of parameters — bias θ_{i0}, input weight θ_{i1}, output weight φ_i — so a shallow network is just a sum of independent per-unit linear models, and widening the layer adds three parameters per unit.
DEMO STEPS: 4 guided steps — implement the step player in #ui

