// @FIGURE_CODE_BEGIN
var W = 640, H = 480;
var draw = SVG().addTo('#container').size('100%', '100%');
draw.viewbox(0, 0, W, H);

var ORANGE = '#d98862', BLACK = '#111', BLUE = '#1f6fb2';
var state = { N: 3, labeled: true, selected: -1 };

var steps = [
  { title: 'The fully labeled network', narration: 'Panel (a) shows every parameter: orange bias connections carry θᵢ₀ into each hidden unit and φ₀ into the output, black connections from x carry θᵢ₁, and hidden-to-output connections carry φᵢ.', state: { labeled: true, N: 3, selected: -1 } },
  { title: 'Trace one hidden unit', narration: 'h₂ is highlighted: its incoming bias θ₂₀, input weight θ₂₁, and outgoing weight φ₂ light up together — each hidden unit owns exactly these three parameters, a mini linear-model-plus-activation feeding y.', state: { labeled: true, N: 3, selected: 1 } },
  { title: 'Same network, clean view', narration: 'Panel (b): the architecture is unchanged, but the weight names and bias nodes are hidden. Switching back and forth confirms the labels are annotation, not structure.', state: { labeled: false, N: 3, selected: -1 } },
  { title: 'Grow the hidden layer', narration: 'Drag the slider to add hidden units: x and y stay fixed while each new unit hᵢ appears with its own θᵢ₀, θᵢ₁, and φᵢ. Capacity grows one independent three-parameter unit at a time.', state: { labeled: true, N: 5, selected: -1 } }
];
var stepIdx = 0;

var SUB = ['₀','₁','₂','₃','₄','₅','₆'];

function hiddenY(i, N) {
  var span = Math.min(340, 95 * (N - 1) + 40);
  if (N === 1) return H / 2;
  return H / 2 - span / 2 + span * (i / (N - 1));
}

function arrowLine(g, x1, y1, x2, y2, color, width) {
  var r = 26;
  var dx = x2 - x1, dy = y2 - y1, len = Math.sqrt(dx*dx + dy*dy);
  var ux = dx / len, uy = dy / len;
  var sx = x1 + ux * r, sy = y1 + uy * r;
  var ex = x2 - ux * (r + 3), ey = y2 - uy * (r + 3);
  g.line(sx, sy, ex, ey).stroke({ color: color, width: width });
  var a = 11, w = 4.5;
  var bx = ex - ux * a, by = ey - uy * a;
  var px = -uy, py = ux;
  g.polygon([[ex, ey], [bx + px * w, by + py * w], [bx - px * w, by - py * w]]).fill(color);
  return { mx: (sx + ex) / 2, my: (sy + ey) / 2, ux: ux, uy: uy };
}

function haloText(g, str, cx, cy, size, color, opacity) {
  return g.text(str)
    .font({ size: size, family: 'serif', style: 'italic' })
    .fill(color).opacity(opacity)
    .center(cx, cy)
    .attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
}

function redraw() {
  draw.clear();
  var N = state.N, labeled = state.labeled, sel = state.selected;
  var xX = 100, hX = 330, yX = 560;
  var biasHX = 100, biasHY = 78;   // hidden-layer bias node (upper left)
  var biasYX = 330, biasYY = 62;   // output bias node (top)
  var yY = H / 2;

  function dimOf(unitIdx, role) {
    if (sel < 0) return 1;
    if (role === 'other') return 0.15;
    if (role === 'hnode') return (unitIdx === sel) ? 1 : 0.15;
    return (unitIdx === sel) ? 1 : 0.12;
  }

  // panel label
  draw.text(labeled ? 'a)' : 'b)').font({ size: 20, family: 'serif', style: 'italic' }).move(6, 4).fill('#000');

  var geoGroup = draw.group();
  var labelGroup = draw.group();

  var hYs = [];
  for (var i = 0; i < N; i++) hYs.push(hiddenY(i, N));

  // φ₀ edge (bias -> y), only in labeled view
  if (labeled) {
    var g0 = geoGroup.group().opacity(dimOf(0, 'other'));
    var m0 = arrowLine(g0, biasYX, biasYY, yX, yY, ORANGE, 2);
    haloText(labelGroup, 'φ' + SUB[0], m0.mx + 16, m0.my - 12, 17, ORANGE, dimOf(0, 'other'));
  }

  for (var j = 0; j < N; j++) {
    (function (i) {
      var hy = hYs[i];
      var above = hy < yY - 4, below = hy > yY + 4;

      // x -> h_i (black, θᵢ₁)
      var gX = geoGroup.group().opacity(dimOf(i, 'inX'));
      var mX = arrowLine(gX, xX, yY, hX, hy, BLACK, sel === i ? 3 : 1.8);
      // h_i -> y (black, φᵢ)
      var gO = geoGroup.group().opacity(dimOf(i, 'out'));
      var mO = arrowLine(gO, hX, hy, yX, yY, sel === i ? BLUE : BLACK, sel === i ? 3 : 1.8);
      // bias -> h_i (orange, θᵢ₀), only in labeled view
      var mB = null, oB = 1;
      if (labeled) {
        oB = dimOf(i, 'inB');
        var gB = geoGroup.group().opacity(oB);
        mB = arrowLine(gB, biasHX, biasHY, hX, hy, ORANGE, sel === i ? 3 : 1.6);
      }

      if (labeled) {
        var oX = dimOf(i, 'inX'), oO = dimOf(i, 'out');
        // θᵢ₀ label: orange, offset perpendicular from bias-edge midpoint
        var pxB = -mB.uy, pyB = mB.ux;
        haloText(labelGroup, 'θ' + SUB[i + 1] + SUB[0],
          mB.mx + pxB * 14, mB.my + pyB * 14 - 4, 15, ORANGE, oB);
        // θᵢ₁ label: black, near arrow midpoint, offset perpendicular
        var pxX = -mX.uy, pyX = mX.ux;
        var offX = (above ? 1 : -1);
        haloText(labelGroup, 'θ' + SUB[i + 1] + SUB[1],
          mX.mx + pxX * 13 * offX, mX.my + pyX * 13 * offX, 15, BLACK, oX);
        // φᵢ label: offset perpendicular from output-edge midpoint
        var pxO = -mO.uy, pyO = mO.ux;
        var offO = (above ? -1 : 1);
        haloText(labelGroup, 'φ' + SUB[i + 1],
          mO.mx + pxO * 14 * offO + 6, mO.my + pyO * 14 * offO, 17,
          sel === i ? BLUE : '#333', oO);
      }
    })(j);
  }

  // nodes on top of edges
  var nodeG = draw.group();
  function circleNode(cx, cy, color, op) {
    var g = nodeG.group().opacity(op);
    g.circle(52).center(cx, cy).fill('#fff').stroke({ color: color, width: 2.5 });
    return g;
  }

  var otherOp = (sel < 0) ? 1 : 0.15;

  // bias nodes — only in labeled (panel a) view
  if (labeled) {
    var bh = circleNode(biasHX, biasHY, ORANGE, otherOp);
    bh.text('1').font({ size: 20, family: 'serif' }).fill(ORANGE).center(biasHX, biasHY);
    var by = circleNode(biasYX, biasYY, ORANGE, otherOp);
    by.text('1').font({ size: 20, family: 'serif' }).fill(ORANGE).center(biasYX, biasYY);
  }

  // x node
  var xn = circleNode(xX, yY, BLACK, otherOp);
  xn.text('x').font({ size: 22, family: 'serif', style: 'italic' }).fill('#000').center(xX, yY);

  // y node
  var yn = circleNode(yX, yY, BLACK, otherOp);
  yn.text('y').font({ size: 22, family: 'serif', style: 'italic' }).fill('#000').center(yX, yY);

  // hidden nodes: ReLU glyph centered, hᵢ label centered below glyph
  for (var k = 0; k < N; k++) {
    (function (i) {
      var hy = hYs[i];
      var op = dimOf(i, 'hnode');
      var g = circleNode(hX, hy, sel === i ? BLUE : BLACK, op);
      // small ReLU glyph in upper half of circle
      g.polyline([[hX - 13, hy - 2], [hX - 1, hy - 2], [hX + 11, hy - 14]])
        .fill('none').stroke({ color: '#8fd0c5', width: 3.5, linecap: 'round', linejoin: 'round' });
      // hᵢ label centered in lower half, clear of glyph and border
      g.text('h' + SUB[i + 1]).font({ size: 15, family: 'serif', style: 'italic' })
        .fill('#000').center(hX, hy + 11);
      g.css('cursor', 'pointer');
      g.on('click', function () {
        state.selected = (state.selected === i) ? -1 : i;
        redraw();
      });
      g.on('mousemove', function (e) {
        showTooltip('h' + (i + 1) + ': owns θ' + (i + 1) + '₀, θ' + (i + 1) + '₁, φ' + (i + 1) + ' — click to isolate', e);
      });
      g.on('mouseleave', hideTooltip);
    })(k);
  }

  // parameter count annotation
  var total = 3 * N + 1;
  draw.text(labeled
      ? 'parameters: 3×' + N + ' + 1 (φ₀) = ' + total
      : 'parameters: 3×' + N + ' + 1 = ' + total + ' (same network)')
    .font({ size: 13, family: 'serif' }).fill('#555').move(W - 240, H - 26);
}

function applyState() {
  document.getElementById('labelViewInput').checked = state.labeled;
  document.getElementById('hiddenUnitCountInput').value = state.N;
  document.getElementById('hiddenUnitCountVal').value = state.N;
  redraw();
}

function toggle_labelView(on) { state.labeled = on; state.selected = -1; redraw(); }
function update_hiddenUnitCount(v) { state.N = v; state.selected = -1; redraw(); }

function goStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[stepIdx];
  state.labeled = s.state.labeled;
  state.N = s.state.N;
  state.selected = s.state.selected;
  document.getElementById('demoNarration').textContent = s.title + ' — ' + s.narration;
  document.getElementById('stepLabel').textContent = (stepIdx + 1) + '/' + steps.length;
  applyState();
}
function nextStep() { goStep(stepIdx + 1); }
function prevStep() { goStep(stepIdx - 1); }

goStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: A shallow neural network computes y as a linear combination (weights φ) of hidden units, where each hidden unit h_i is itself a linear function (weights θ_{i0}, θ_{i1}) of the input x passed through an activation — so the θ parameters govern the input-to-hidden transformation and the φ parameters govern the hidden-to-output combination.
KEY INSIGHT (what students should walk away understanding): Every hidden unit contributes exactly one self-contained trio of parameters — bias θ_{i0}, input weight θ_{i1}, output weight φ_i — so a shallow network is just a sum of independent per-unit linear models, and widening the layer adds three parameters per unit.
DEMO STEPS: 4 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "A shallow neural network computes y as a linear combination (weights φ) of hidden units, where each hidden unit h_i is itself a linear function (weights θ_{i0}, θ_{i1}) of the input x passed through an activation — so the θ parameters govern the input-to-hidden transformation and the φ parameters govern the hidden-to-output combination.",
  "figureType": "network_diagram",
  "elements": [
    "input node x (circle, left)",
    "bias node labeled 1 feeding the hidden layer (upper left, orange)",
    "bias node labeled 1 feeding the output y (top, orange)",
    "three hidden unit nodes h_1, h_2, h_3 (circles, center column, each with a small ReLU-like activation glyph)",
    "output node y (circle, right)",
    "orange directed edges from the hidden-layer bias node to each h_i, labeled θ_{10}, θ_{20}, θ_{30}",
    "black directed edges from x to each h_i, labeled θ_{11}, θ_{21}, θ_{31}",
    "black directed edges from each h_i to y, labeled φ_1, φ_2, φ_3",
    "orange directed edge from the output bias node to y, labeled φ_0",
    "arrowheads on all edges indicating left-to-right data flow",
    "panel-style labels distinguishing the clean view and the fully labeled view"
  ],
  "interactions": [
    {
      "id": "selectHiddenUnit",
      "type": "click",
      "teaches": "Each hidden unit h_i owns exactly one slice of the parameterization: its bias θ_{i0}, its input weight θ_{i1}, and its output weight φ_i — clicking a unit isolates the computation y's dependence on that single unit and shows the parameters travel together per neuron",
      "label": "Select hidden unit"
    },
    {
      "id": "labelView",
      "type": "toggle",
      "label": "Diagram view",
      "options": [
        "Clean (panel b)",
        "Labeled (panel a)"
      ],
      "default": "Labeled (panel a)",
      "teaches": "The underlying architecture is identical in both views; the labeled view makes the full θ and φ parameter names explicit while the clean view shows the same network stripped down to its structure",
      "default_note": ""
    },
    {
      "id": "hiddenUnitCount",
      "type": "slider",
      "label": "Number of hidden units",
      "range": [
        1,
        6,
        1
      ],
      "default": 3,
      "teaches": "The architecture scales by adding hidden units, and each added unit contributes exactly 3 new parameters (θ_{i0}, θ_{i1}, φ_i) — so parameter count grows linearly with hidden-layer width while x and y stay fixed"
    }
  ],
  "demo_steps": [
    {
      "title": "The fully labeled network",
      "narration": "Panel (a) shows every parameter: orange bias connections carry θ_{i0} into each hidden unit and φ_0 into the output, black connections from x carry θ_{i1}, and hidden-to-output connections carry φ_i.",
      "state": {
        "labelView": "Labeled (panel a)",
        "hiddenUnitCount": 3
      }
    },
    {
      "title": "Trace one hidden unit",
      "narration": "Click h_2: its incoming bias θ_{20}, input weight θ_{21}, and outgoing weight φ_2 light up together — each hidden unit owns exactly these three parameters, a mini linear-model-plus-activation feeding y.",
      "state": {
        "labelView": "Labeled (panel a)",
        "hiddenUnitCount": 3
      }
    },
    {
      "title": "Same network, clean view",
      "narration": "Toggle to panel (b): the architecture is unchanged, but the weight names are hidden. Switching back and forth confirms the labels are annotation, not structure.",
      "state": {
        "labelView": "Clean (panel b)",
        "hiddenUnitCount": 3
      }
    },
    {
      "title": "Grow the hidden layer",
      "narration": "Drag the slider to add hidden units: x and y stay fixed while each new unit h_i appears with its own θ_{i0}, θ_{i1}, and φ_i. The network's capacity grows one independent three-parameter unit at a time.",
      "state": {
        "labelView": "Labeled (panel a)",
        "hiddenUnitCount": 5
      }
    }
  ],
  "keyInsight": "Every hidden unit contributes exactly one self-contained trio of parameters — bias θ_{i0}, input weight θ_{i1}, output weight φ_i — so a shallow network is just a sum of independent per-unit linear models, and widening the layer adds three parameters per unit.",
  "reconstructionNotes": "Left-to-right layered layout: x at mid-left, hidden units stacked vertically in a center column, y at mid-right. Two orange bias nodes labeled 1: one above-left feeding all hidden units, one at top feeding y directly with edge φ_0. Bias-originated edges in orange; all other edges in black; θ labels on input-to-hidden edges, φ labels on hidden-to-output edges, in italic serif math styling positioned near each edge midpoint. Each hidden unit circle contains a small activation-function glyph (short ReLU-style bent line). Clicking a hidden unit should highlight only its own three parameter edges/labels (plus dim the rest of the graph) — the per-unit parameter bundle is the lesson. In clean view, remove all weight labels and optionally the bias label emphasis but keep identical node/edge structure. When the slider changes hidden-unit count, units fan out symmetrically around the vertical center, with h_i labels, θ_{i0}/θ_{i1}/φ_i labels regenerating consistently for each unit."
}

