var SUB = ['₀','₁','₂','₃','₄','₅','₆'];

function hiddenY(i, N) {
  var span = Math.min(340, 95 * (N - 1) + 40);
  if (N === 1) return H / 2;
  return H / 2 - span / 2 + span * (i / (N - 1));
