function arrowLine(g, x1, y1, x2, y2, color, width) {
  var r = 27;
  var dx = x2 - x1, dy = y2 - y1, len = Math.sqrt(dx*dx + dy*dy);
  var ux = dx / len, uy = dy / len;
  var sx = x1 + ux * r, sy = y1 + uy * r;
  var ex = x2 - ux * (r + 3), ey = y2 - uy * (r + 3);
  g.line(sx, sy, ex, ey).stroke({ color: color, width: width });
