      haloText(g, 'h' + SUB[i + 1], hX, hy, 16, '#000', 1);
      g.css('cursor', 'pointer');
      g.on('click', function () {
        state.selected = (state.selected === i) ? -1 : i;
        redraw();
      });
      g.on('mousemove', function (e) {
        showTooltip('h' + (i + 1) + ': owns θ' + (i + 1) + '₀, θ' + (i + 1) + '₁, φ' + (i + 1) + ' — click to isolate', e);
      });
      g.on('mouseleave', hideTooltip);
    })(k);
  }

  // parameter count lives in the UI panel, not on the canvas
  document.getElementById('paramCount').textContent =
    'Parameters: 3×' + N + ' + 1 (φ₀) = ' + (3 * N + 1) +
    (labeled ? '' : ' — same network, labels hidden');
}

function applyState() {
  document.getElementById('labelViewInput').checked = state.labeled;
  document.getElementById('hiddenUnitCountInput').value = state.N;
  document.getElementById('hiddenUnitCountVal').value = state.N;
  redraw();
}

function toggle_labelView(on) { state.labeled = on; state.selected = -1; redraw(); }
function update_hiddenUnitCount(v) { state.N = v; state.selected = -1; redraw(); }

function goStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[stepIdx];
  state.labeled = s.state.labeled;
  state.N = s.state.N;
  state.selected = s.state.selected;
  document.getElementById('demoNarration').textContent = s.title + ' — ' + s.narration;
  document.getElementById('stepLabel').textContent = (stepIdx + 1) + '/' + steps.length;
  applyState();
}
function nextStep() { goStep(stepIdx + 1); }
function prevStep() { goStep(stepIdx - 1); }

goStep(0);
window.__markRendered();
// @FIGURE_CODE_END

